<script setup lang="ts">definePageMeta({layout:"default"});useSeoMeta({title:"ارتقا و بسته‌ها | هفت‌سو",robots:"noindex,nofollow"});const{buy,entitlements,load,message,pending,products}=useMonetization();onMounted(load);</script><template><main id="main-content" class="promotions-page content-container"><header><p class="eyebrow">بیشتر دیده شوید</p><h1>ارتقای آگهی و بسته‌های حرفه‌ای</h1><p>قیمت شفاف، اعتبار قابل پیگیری و فعال‌سازی زمان‌بندی‌شده.</p></header><UiState v-if="pending" kind="loading" title="در حال دریافت بسته‌ها" description="قیمت‌های معتبر بررسی می‌شوند."/><template v-else><EntitlementBalance :items="entitlements"/><section class="monetization-grid"><MonetizationProductCard v-for="product in products" :key="product.id" :product="product" @buy="buy"/></section></template><p v-if="message" class="post-action-message" role="status">{{message}}</p></main></template>
